css:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: Arial, sansl-serif;
    font-size: 11px;
    padding: 15px;
    color: #333;
}
hr {
    margin-top: 16px;
    margin-bottom: 10px;
    border: 0;
    border-top: 1px solid #E2E8F0;
}
.header {
    margin-bottom: 15px;
    overflow: hidden;
}

.logo {
    float: left;
    font-weight: bold;
    font-size: 13px;
}

.quotation-title {
    float: right;
    text-align: right;
}

.quotation-title h1 {
    font-size: 20px;
    font-weight: bold;
    margin-top: 0px;
    margin-bottom: 3px;
}

.quotation-number {
    color: #666;
    font-size: 11px;
}

.clearfix::after {
    content: "";
    display: table;
    clear: both;
}

.two-column {
    margin-bottom: 15px;
    overflow: hidden;
}

.column-left {
    float: left;
    width: 49%;
}

.column-right {
    float: right;
    width: 49%;
}

.customer-info-box {
    background-color: #F7FAFC;
    padding: 8px;
    border-radius: 5px;
    font-size:10px;
    vertical-align:top;
    
    border: 1px solid #E2E8F0;
}

.customer-info-box h3 {
    font-size: 11px;
    font-weight: bold;
    margin-bottom: 8px;
    margin-top: auto;
    color: #333;
    padding-bottom: 6px;
    padding-left: 6px;
}
.info-box {
    background-color: #F7FAFC;
    padding: 8px;
    margin-bottom: 0;
    border-radius: 5px;
    font-size:10px;
    
    border: 1px solid #E2E8F0;
}

.info-box h3 {
    font-size: 11px;
    font-weight: bold;
    margin-bottom: 8px;
    margin-top: auto;
    color: #333;
    padding-bottom: 6px;
    padding-left: 6px;
    border-bottom: 1px solid #E2E8F0;
}

.info-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: -10px;
    margin-left: -4px;
    margin-bottom: 0px;
}

.info-table td {
    padding: 3px 10px;
    font-size: 11px;
}

.info-table td:first-child {
    font-weight: normal;
    width: 30%;
    color: #333;
}

.info-table td:last-child {
    color: #666;
}


.customer-info-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: -10px;
    margin-left: -4px;
    margin-bottom: 0px;
}

.customer-info-table td {
    padding: 3px 10px;
    font-size: 11px;
}

.customer-info-table td:first-child {
    font-weight: normal;
    width: 29%;
    color: #333;
}

.customer-info-table td:last-child {
    color: #666;
}






.section-title {
    font-size: 12px;
    font-weight: bold;
    margin: -3px 0px -12px 0px;
}

.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 60;
    border-radius: 8px;
    overflow: hidden;
}

.items-table th {
    background-color: #F7FAFC;
    padding: 10px;
    text-align: left;
    font-weight: bold;
    font-size: 11px;
    border-bottom: 1px solid #ddd;
    color: black;
    /* Remove vertical borders between columns */
    border-left: none;
    border-right: none;
}

.items-table th:nth-child(3),
.items-table th:nth-child(4) {
    text-align: right;
}
.items-table th:nth-child(1) {
    width:15%;
}
.items-table th:nth-child(2) {
    width:50%;
}

.items-table td {
    padding: 10px;
    /* Remove all cell borders, only keep bottom border for row separation */
    border-bottom: 1px solid #ddd;
    border-left: none;
    border-right: none;
    font-size: 11px;
}

.item-description {
    /*font-weight: bold;*/
    margin-bottom: 3px;
}

.item-details {
    color: #666;
    font-size: 9px;
}

.totals-row td {
    border-bottom: 1px solid #F7FAFC;
    padding: 8px 10px;
    font-size: 11px;
    background-color:#F7FAFC;
}


.totals-row td:first-child {
    text-align: right;
    font-weight: 600;
}

.totals-row td:last-child {
    text-align: right;
    font-weight: 600;
}

.final-total-row td {
    background-color: #E8F1FC;
    border-bottom: none;
    padding: 10px;
    font-weight: bold;
    font-size: 11px;
}

.final-total-row td:first-child {
    text-align: right;
}

.final-total-row td:last-child {
    text-align: right;
}

.notice-box {
    background-color: #F7FAFC;
    padding: 12px;
    margin: 15px 0;
    font-size: 10px;
    line-height: 1.5;
}

.notice-title {
    font-weight: bold;
    display: inline;
}

.footer {
    text-align: center;
    font-size: 10px;
    color: #666;
    margin-top: 15px;
    line-height: 1.4;
}

.approval-table {
    width: 100%;
    border-collapse: collapse;
    line-height: 1px;
}

.approval-table td {
    padding: 3px 0;
    font-size: 11px;
}

.approval-table td:first-child {
    font-weight: normal;
    width: 40%;
    color: #333;
}
